-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: update only genuinely empty published lessons; add each origin/type once.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":1,"skill":"دراسة العصر الأندلسي في سياقه","passage":"تنوعت الحياة الثقافية في الأندلس عبر قرون ومدن متعددة، ولذلك ينبغي التمييز بين المراحل والأمكنة عند دراسة الإنتاج الأدبي. نموذج ضاديوم المستقل: يصف راويًا مجلس قراءة يجمع أصدقاء يناقشون نصًا، ولا يُعد شهادة تاريخية عن مجلس أندلسي بعينه.","prompt":"ما الذي يمنع التعميم غير الدقيق عن الأندلس؟","correct":"تحديد الزمان والمكان والمصادر","w1":"اعتبار كل العصور واحدة","w2":"نسخ وصف خيالي","w3":"إلغاء المقارنة","practice":"ضع خطًا زمنيًا موجزًا لفترتين أندلسيتين مع مصدرين موثوقين ونص أدبي متعلق بكل فترة."},{"n":2,"skill":"خصائص الأساليب الأندلسية","passage":"يظهر في الأدب الأندلسي اهتمام بالوصف والموشح وأشكال أخرى بحسب العصر والنص، ولا تكفي هذه السمات وحدها لنسبة قصيدة مجهولة. في وصف مستقل «تنعكس الأشجار على صفحة الماء في ساحة هادئة» تمثل الصورة تدريبًا على التحليل لا مقتطفًا تاريخيًا.","prompt":"ما أفضل دليل على سمة فنية في الأدب الأندلسي؟","correct":"شاهد موثق من نص ينتمي للفترة","w1":"تخمين العصر من الاسم","w2":"وصف معاصر بلا مصدر","w3":"تشابه كلمة واحدة","practice":"اختر نصًا أندلسيًا من مقرر موثوق واستخرج صورتين فنيتين مع تفسير وظيفتهما."},{"n":3,"skill":"فنون النثر الأندلسي","passage":"تتنوع فنون النثر بين الرسائل والخطب والمناظرات وغير ذلك في سياقات تاريخية مختلفة. يميز القارئ الرسالة من المناظرة بالنظر إلى المخاطب والغرض وتبادل الحجج، لا بتكرار سجع اصطناعي.","prompt":"أي علامة تميز المناظرة عن الرسالة الفردية غالبًا؟","correct":"تبادل الرأي والحجج بين أطراف","w1":"وجود تاريخ فقط","w2":"استعمال اسم مدينة","w3":"غياب المخاطب","practice":"قارن مقطع رسالة أندلسية بمقطع مناظرة موثقين من حيث البنية والحجة والنبرة."},{"n":4,"skill":"الأغراض الشعرية وتنوع التجربة","passage":"يمكن للمديح والرثاء والحنين ووصف الطبيعة أن تظهر في أشعار أندلسية مختلفة، لكن تحديد الغرض يستلزم قراءة الأبيات وربطها بالمخاطب والعاطفة. تدريب مستقل يصف شاعرًا يتذكر مدينته البعيدة دون ذكر بيت أو شاعر تاريخي.","prompt":"ما الدليل الأقوى على غرض الحنين في قصيدة؟","correct":"ألفاظ وصور مثبتة في الأبيات","w1":"اسم مدينة وحده","w2":"طول البحر فقط","w3":"اسم العصر دون نص","practice":"استخرج شاهدين من قصيدتين أندلسيتين موثقتين وحدد الغرض وقرائن العاطفة."},{"n":5,"skill":"المعنى والخيال والوزن في الشعر","passage":"تحليل القصيدة يجمع الفكرة والمعجم والصورة والوزن والقافية؛ فقد تتشابه قصيدتان في البحر وتختلفان في الغرض. يوضح نموذج من ضاديوم أن «الريح تنادي النافذة» تشخيص مجازي، لكنه لا يمثل بيتًا أندلسيًا.","prompt":"ما الذي يحلل «الريح تنادي» بلاغيًا؟","correct":"إسناد فعل إنساني إلى الريح","w1":"عدّ الكلمتين متضادتين","w2":"ذكر القافية","w3":"إثبات واقعة طبيعية حرفية","practice":"اختر بيتًا موثقًا وحدد معناه وصورة واحدة والتفعيلة والقافية مع الشرح."},{"n":6,"skill":"تحليل الحنين في شعر ابن زيدون","passage":"يتطلب نص «حنين وشوق» لابن زيدون الرجوع إلى أبياته المعتمدة قبل تحديد المخاطَب أو موضع الصورة. في نثر مستقل: «إذا رأيت الطريق القديم تذكرت وجوه رفاقي» دلالة على الحنين، لكنها ليست منسوبة إلى الشاعر.","prompt":"ما العاطفة في المثال النثري المستقل؟","correct":"الحنين","w1":"اللامبالاة","w2":"التشفي","w3":"الفخر العسكري","practice":"وثق بيتًا صحيحًا من النص المقرر، ثم حلل لفظًا وصورة يدلان على الحنين وأثرهما."},{"n":7,"skill":"العروض: بنية البحر الطويل","passage":"البحر الطويل التام في إحدى صوره الأصلية يقوم على «فعولن مفاعيلن فعولن مفاعيلن» في كل شطر، مع صور الزحاف والعلة الواردة في العروض. يتطلب الحكم على البيت التقطيع من المنطوق لا من رسم الكلمات.","prompt":"ما التفعيلة التي تبدأ بها الصيغة الأصلية للطويل؟","correct":"فعولن","w1":"فاعلاتن","w2":"متفاعلن","w3":"مستفعلن","practice":"احصل على بيت ثابت المصدر من الطويل وقطعه ثم افحص التفعيلة الثانية والضرب العروضي."},{"n":8,"skill":"أدب المجالس دون اقتباسات ملفقة","passage":"لتحليل «أدب المجالس» لابن حزم لا بد من النص الأصلي والصفحة، وخاصة عند نسبة حكم خلقي أو نصيحة للمؤلف. في حوار مستقل يختلف طالبان في رأي ويستمع كل منهما حتى نهاية الحديث؛ يصح تدريبهما على آداب النقاش دون عدّه كلام ابن حزم.","prompt":"ما سلوك المجلس الجيد في المثال؟","correct":"الإنصات قبل الرد","w1":"المقاطعة المتكررة","w2":"السخرية","w3":"نسبة الأقوال بلا دليل","practice":"استخرج نصيحة موثقة من كتاب ابن حزم ثم ناقش تطبيقها في جلسة تعلم معاصرة."},{"n":9,"skill":"قراءة ترجمة ابن خفاجة","passage":"تحتاج سيرة ابن خفاجة إلى مصدر أدبي وتاريخي معتبر للتأكد من التاريخ والآثار والأوصاف، فلا ننسب إليه قولًا من صياغة ضاديوم. في تدريب مستقل يكتب الطالب بطاقة ترجمة تشمل العصر والبيئة والنص الموثق والشواهد الفنية.","prompt":"أي جزء أساسي في بطاقة الترجمة الأدبية؟","correct":"عمل موثق مع مصدره","w1":"تاريخ مختلق","w2":"حكاية بلا مرجع","w3":"اسم العنوان وحده","practice":"أعد بطاقة ترجمة دقيقة لابن خفاجة تتضمن عملًا أدبيًا وصورة فنية من مصدر موثق."},{"n":10,"skill":"الرثاء السياسي وفهم السياق","passage":"يستدعي نص «من رثاء الممالك الزائلة» لابن عبدون معرفة سياقه التاريخي وشواهده المقررة قبل وصف أطراف الحدث أو كتابة أبيات منسوبة إليه. مثال مستقل: «يرى الراوي سور المدينة القديم ويشعر بزوال أيام مضت» يوحي بالفقد لا يمثل القصيدة.","prompt":"ما الشعور الذي يبرزه المثال النثري؟","correct":"الأسى على الماضي","w1":"التفاخر بعمل تجاري","w2":"السعادة بمباراة","w3":"اللامبالاة","practice":"بعد قراءة الأبيات الأصلية، استخرج شاهدًا للمرثية وفسر أثر الصورة التاريخية."},{"n":11,"skill":"العروض: البحر المديد","passage":"البحر المديد في أصل دائرته العروضية يرتبط بتتابع «فاعلاتن فاعلن فاعلاتن فاعلن»، ويُدرس غالبًا مجزوءًا في الاستعمال الشعري؛ ينبغي اعتماد صورة البيت الحقيقية ومراجع العروض قبل الحكم على عدد التفعيلات.","prompt":"ما التفعيلة الأولى في أصل نسق المديد؟","correct":"فاعلاتن","w1":"فعولن","w2":"متفاعلن","w3":"مفاعلتن","practice":"استخدم مثالًا موثقًا للمديد، وقطعه كتابة عروضية وحدد صورته المستعملة دون اختلاق بيت."},{"n":12,"skill":"بنية الرسائل الجدية","passage":"قراءة رسالة جدية لابن زيدون تستلزم النص المحقق لفهم المرسل والمخاطب والغرض السياسي أو الشخصي بحسب الوثيقة، ولا يثبت ذلك من العنوان وحده. مثال مستقل: رسالة اعتذار رسمية فيها سبب وطلب وإغلاق مهذب، تساعد على مقارنة بناء الرسائل فقط.","prompt":"ما العنصر الذي يوضح غرض الرسالة؟","correct":"متن يبين السبب والطلب","w1":"اسم المؤلف وحده","w2":"الخط الجميل","w3":"عدد الكلمات","practice":"استخرج من رسالة ابن زيدون الأصلية خطابًا للمخاطب وحجة موثقة ثم قارنه برسالة حديثة من إنشائك."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=11
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027' AND cu.id='79a8732d-6a86-46cd-8cad-31673af20a0c'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.title='أدب 212 — الأدب والنصوص' AND u.semester=2 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF char_length(coalesce(target_content,''))<350 THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف الحادي عشر، الفصل الثاني. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.'||E'\n\n'||'المدخل السابق المحفوظ: '||coalesce(target_content,''),
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف الحادي عشر%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_RELIGIOUS_G11_T2_ADAB212_ORIGINAL_20261008','notOfficialBook',true,'ocrReview','pending','options',CASE (r.n % 4) WHEN 0 THEN jsonb_build_array(r.correct,r.w1,r.w2,r.w3) WHEN 1 THEN jsonb_build_array(r.w1,r.correct,r.w2,r.w3) WHEN 2 THEN jsonb_build_array(r.w1,r.w2,r.correct,r.w3) ELSE jsonb_build_array(r.w1,r.w2,r.w3,r.correct) END),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_RELIGIOUS_G11_T2_ADAB212_ORIGINAL_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_RELIGIOUS_G11_T2_ADAB212_ORIGINAL_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_RELIGIOUS_G11_T2_ADAB212_ORIGINAL_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;